public class SlidingWindowRateLimitMiddleware
{
    private readonly ConnectionMultiplexer _redis;
    private readonly string _script = @"
        local key = KEYS[1]
        local window = tonumber(ARGV[1])
        local max = tonumber(ARGV[2])
        local now = tonumber(ARGV[3])
        local data = redis.call('HMGET', key, 'prev', 'curr', 'start')
        local prev = tonumber(data[1]) or 0
        local curr = tonumber(data[2]) or 0
        local start = tonumber(data[3]) or now
        if now - start >= window then
            prev = curr
            curr = 0
            start = now
        end
        local overlap = (window - (now - start)) / window
        local weighted = prev * overlap + curr
        if weighted < max then
            curr = curr + 1
            redis.call('HMSET', key, 'prev', prev, 'curr', curr, 'start', start)
            redis.call('EXPIRE', key, window * 2)
            return {1, max - math.floor(weighted) - 1}
        end
        return {0, 0}
    ";

    public async Task InvokeAsync(HttpContext context)
    {
        var key = $"rate:{context.User.Identity?.Name ?? context.Connection.RemoteIpAddress}";
        var now = (long)(DateTimeOffset.UtcNow.ToUnixTimeSeconds());
        var result = await _redis.GetDatabase().ScriptEvaluateAsync(
            _script,
            new RedisKey[] { key },
            new RedisValue[] { 60, 100, now });

        var allowed = (long)result;
        if (allowed == 0)
        {
            context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
            await context.Response.WriteAsync("Rate limited");
            return;
        }

        await _next(context);
    }
}
